        """Call the underlying wgpu release function;
        works even on leaked objects"""
        if self._cdata == ffi.NULL:
            return
        ffi.gc(self._cdata, None)
        lib.wgpuAdapterRelease(self._cdata)
        # ffi.release(self._cdata)
        self._cdata = ffi.NULL

